<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Кто попадает под казначейское сопровождение в 2026 году?", "acceptedAnswer": {"@type": "Answer", "text": "Целевые средства из бюджета: авансы по госконтрактам от 100 млн ₽ (кроме ГОЗ), расчёты по ГОЗ и закупкам у единственного поставщика свыше 3 млн ₽, авансы соисполнителей свыше 3 млн ₽, субсидии и бюджетные инвестиции юрлицам. Перечень — в статье 5 Закона № 426-ФЗ."}}, {"@type": "Question", "name": "От какой суммы казначейское сопровождение в 2026 году?", "acceptedAnswer": {"@type": "Answer", "text": "Базовый порог для авансов по обычным госконтрактам — 100 млн ₽. Для ГОЗ, закупок у единственного поставщика и расчётов соисполнителей — свыше 3 млн ₽. Для контрактов бюджетных и автономных учреждений за счёт субсидий — от 10 млн ₽."}}, {"@type": "Question", "name": "Где закреплён перечень случаев казначейского сопровождения?", "acceptedAnswer": {"@type": "Answer", "text": "В законе о федеральном бюджете на текущий год. На 2026 год это статья 5 Федерального закона от 28.11.2025 № 426-ФЗ. Базовые правила — в главе 24.4 Бюджетного кодекса (ст. 242.23–242.27)."}}, {"@type": "Question", "name": "Сопровождаются ли субсидии и бюджетные инвестиции?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Субсидии юрлицам (кроме субсидий федеральным учреждениям), бюджетные инвестиции по статье 80 БК и гранты в форме субсидий подлежат сопровождению без порога по сумме — по факту получения целевых средств."}}, {"@type": "Question", "name": "Что изменилось в перечне в 2026 году?", "acceptedAnswer": {"@type": "Answer", "text": "Перечень стал шире. В частности, порог для контрактов бюджетных и автономных учреждений субъекта снижен с 50 до 10 млн ₽, прямо включены субсидии по концессиям и ГЧП, расширен охват бюджетных кредитов регионам."}}, {"@type": "Question", "name": "Кто не попадает под сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Контракты ниже порога, а также средства, исключённые статьёй 242.27 БК и частью 4 статьи 5 Закона № 426-ФЗ — организациям кинематографии, региональным и муниципальным СМИ, политическим партиям. В ряде случаев применяется банковское сопровождение вместо казначейского."}}, {"@type": "Question", "name": "Сумма порога считается от цены контракта или от платежа?", "acceptedAnswer": {"@type": "Answer", "text": "От цены контракта. Например, аванс попадает под сопровождение, если цена госконтракта достигает 100 млн ₽, независимо от размера самого авансового платежа."}}, {"@type": "Question", "name": "Кто ведёт казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Территориальный орган Федерального казначейства (ТОФК) по месту открытия лицевого счёта. Для региональных и местных средств сопровождение может вести финансовый орган субъекта или муниципалитета."}}, {"@type": "Question", "name": "В каких случаях контракт подлежит казначейскому сопровождению?", "acceptedAnswer": {"@type": "Answer", "text": "Контракт подлежит казначейскому сопровождению, когда это установлено законом о федеральном бюджете на текущий год или решением Правительства: авансируемые контракты сверх установленного порога, средства гособоронзаказа по 275-ФЗ, целевые субсидии и бюджетные инвестиции юридическим лицам. Конкретные случаи ежегодно закрепляет статья 5 закона о бюджете."}}, {"@type": "Question", "name": "Что такое лимит казначейского сопровождения?", "acceptedAnswer": {"@type": "Answer", "text": "Термин имеет два значения. Порог суммы, с которой сопровождение обязательно: авансы от 100 млн рублей, авансы учреждений за счёт субсидий от 10 млн, отдельные случаи от 3 млн; субсидии и гранты — независимо от суммы. И лимит-остаток целевых средств на лицевом счёте: расходовать можно только в пределах поступивших средств и утверждённых Сведений об операциях."}}, {"@type": "Question", "name": "Попадают ли контракты по национальным проектам и в медицине под казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Да, если контракт финансируется целевыми бюджетными средствами. Субсидии, бюджетные инвестиции и средства национальных проектов (включая здравоохранение) сопровождаются независимо от суммы, а обычные госконтракты — при достижении порогов. Условие о казначейском сопровождении в этом случае включается в контракт."}}]}
</script>
